import{_ as e,o as r,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Making RBD Snapshot-based Mirroring Robust for Disaster Recovery | Ceph Days NYC 2024","description":"","frontmatter":{"title":"Making RBD Snapshot-based Mirroring Robust for Disaster Recovery | Ceph Days NYC 2024","date":"2024-06-18T00:00:00.000Z","updated":"2024-06-18T00:00:00.000Z","tags":["Ceph","RBD","Disaster Recovery","Kubernetes","Snapshot","based Mirroring"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Making_RBD_Snapshot-based_Mirroring_Robust_for_Disaster_Recovery_Ceph_Days_NYC_2024.md","filePath":"posts/2024/Making_RBD_Snapshot-based_Mirroring_Robust_for_Disaster_Recovery_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),t={name:"posts/2024/Making_RBD_Snapshot-based_Mirroring_Robust_for_Disaster_Recovery_Ceph_Days_NYC_2024.md"};function o(s,a,n,_,h,u){return r(),i("div",null,[...a[0]||(a[0]=[l('<p>会议纪要</p><h3 id="会议主题-rbd快照基础镜像功能改进与灾难恢复解决方案" tabindex="-1">会议主题：RBD快照基础镜像功能改进与灾难恢复解决方案 <a class="header-anchor" href="#会议主题-rbd快照基础镜像功能改进与灾难恢复解决方案" aria-label="Permalink to &quot;会议主题：RBD快照基础镜像功能改进与灾难恢复解决方案&quot;">​</a></h3><h3 id="主讲人-raman-raja-ibm软件工程师" tabindex="-1">主讲人：Raman Raja，IBM软件工程师 <a class="header-anchor" href="#主讲人-raman-raja-ibm软件工程师" aria-label="Permalink to &quot;主讲人：Raman Raja，IBM软件工程师&quot;">​</a></h3><h3 id="会议内容概述" tabindex="-1">会议内容概述： <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述：&quot;">​</a></h3><p>Raman Raja在Ceph Days NYC 2024会议上介绍了RBD（RADOS Block Device）快照基础镜像功能的最新改进，旨在增强其在灾难恢复场景下的健壮性。他详细介绍了RBD镜像功能，包括异步复制、两种模式（日志基础镜像和快照基础镜像），以及如何设置和架构。此外，他还讨论了在严格测试中发现的缺陷及其解决方案。</p><h3 id="主要讨论点" tabindex="-1">主要讨论点： <a class="header-anchor" href="#主要讨论点" aria-label="Permalink to &quot;主要讨论点：&quot;">​</a></h3><ol><li><p><strong>RBD镜像功能概述</strong>：</p><ul><li>RBD镜像功能支持异步复制图像，由RBD镜像守护进程执行。</li><li>支持两种模式：日志基础镜像和快照基础镜像。</li><li>快照基础镜像模式下，在主图像上拍摄崩溃一致的镜像快照，并复制快照增量到非主图像。</li></ul></li><li><p><strong>架构与配置</strong>：</p><ul><li>支持单向和双向复制配置，便于故障切换和故障恢复协调。</li><li>使用SEF orchestrator（如SEF ADM或Rook）启动RBD镜像守护进程，配置RBD池和图像进行镜像。</li></ul></li><li><p><strong>故障切换与恢复</strong>：</p><ul><li>计划故障切换时，先降级主图像，创建降级快照，同步到非主图像，然后提升非主图像。</li><li>非计划故障切换时，强制提升非主图像，如果数据未完全同步，图像回滚到完全同步的快照。</li></ul></li><li><p><strong>灾难恢复解决方案</strong>：</p><ul><li>针对Kubernetes工作负载，使用RBD作为存储后端，实现跨区域的数据恢复，确保业务需求在几分钟内恢复。</li><li>解决方案涉及三个Kubernetes集群，包括一个Hub集群和两个管理集群，通过ramen Hub操作符自动化管理。</li></ul></li><li><p><strong>测试中发现的问题与修复</strong>：</p><ul><li>发现并修复了快照对象映射不正确导致的数据损坏问题。</li><li>解决了镜像快照调度器客户端被krbd客户端错误阻止的问题。</li><li>改进了在高延迟环境下镜像守护进程的行为。</li></ul></li><li><p><strong>未来工作</strong>：</p><ul><li>支持镜像组和RBD克隆的镜像。</li><li>优化强制提升时的数据同步效率。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ul><li>RBD快照基础镜像功能已进行多项改进，提高了灾难恢复场景下的健壮性。</li><li>继续开发镜像组和RBD克隆的镜像支持。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>继续测试和优化RBD快照基础镜像功能。</li><li>完成镜像组和RBD克隆的镜像支持开发。</li></ul><h3 id="致谢" tabindex="-1">致谢： <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢：&quot;">​</a></h3><ul><li>感谢Ilia和Sham作为RBD和ramen操作符的维护者。</li></ul><h3 id="结束语" tabindex="-1">结束语： <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语：&quot;">​</a></h3><p>Raman Raja感谢大家的参与和贡献，并期待未来的进一步合作和改进。</p>',15)])])}const R=e(t,[["render",o]]);export{p as __pageData,R as default};
